CREATE TABLE "mutasi_segel" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "mutasi_segel_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"id_barang" bigint NOT NULL,
	"id_satuan_jual" bigint NOT NULL,
	"waktu" timestamp with time zone DEFAULT now() NOT NULL,
	"tanggal_operasional" date NOT NULL,
	"jenis" varchar(10) NOT NULL,
	"qty_masuk" numeric(14, 3) DEFAULT 0 NOT NULL,
	"qty_keluar" numeric(14, 3) DEFAULT 0 NOT NULL,
	"saldo_setelah" numeric(14, 3) NOT NULL,
	"id_mutasi_persediaan" bigint,
	"id_penyesuaian_detail" bigint,
	"id_pengguna" bigint NOT NULL,
	"keterangan" varchar(255),
	CONSTRAINT "chk_mutasi_segel_jenis" CHECK (jenis in ('MASUK','KELUAR','BUKA','OPNAME','KOREKSI')),
	CONSTRAINT "chk_mutasi_segel_qty" CHECK (qty_masuk >= 0 and qty_keluar >= 0 and (qty_masuk > 0) <> (qty_keluar > 0)
        and qty_masuk = trunc(qty_masuk) and qty_keluar = trunc(qty_keluar) and saldo_setelah >= 0)
);
